:root{color-scheme:light;--ink:#162536;--muted:#627183;--line:#dce5e9;--accent:#087e86;--bg:#f3f7f8}
.command-options>div{flex:1;min-width:0}
.search button{flex-shrink:0}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 system-ui,-apple-system,"Segoe UI",sans-serif}main{max-width:1260px;margin:auto;padding:40px 28px}header,.section-heading,.command-actions,.pagination{display:flex;justify-content:space-between;align-items:center;gap:16px}header{margin-bottom:28px}h1{font-size:30px;letter-spacing:-1px;margin:6px 0}h2{font-size:19px;margin:0 0 14px}p{margin:8px 0 18px;color:var(--muted)}.eyebrow{font-size:11px;letter-spacing:2px;color:var(--accent);font-weight:750}.layout{display:grid;grid-template-columns:390px minmax(0,1fr);gap:22px;align-items:start}.card{background:white;border:1px solid var(--line);border-radius:16px;padding:25px;box-shadow:0 8px 30px #18354904}.right-column{display:grid;gap:22px}label{display:block;font-weight:600;font-size:13px;margin:16px 0 6px}input:not([type=checkbox]),textarea,select{width:100%;font:inherit;color:inherit;border:1px solid #c8d6dd;border-radius:8px;padding:10px 12px;background:#fff}input:focus,textarea:focus,select:focus,button:focus-visible{outline:3px solid #b9e4e7;outline-offset:2px}textarea{resize:vertical}.check,.node-option{display:flex;align-items:start;gap:9px}.check input,.node-option input{margin-top:5px;accent-color:var(--accent)}button{font:600 13px/1.5 system-ui;cursor:pointer;border:1px solid transparent;border-radius:8px;background:var(--accent);color:#fff;padding:10px 15px}button:hover{filter:brightness(.96)}button.secondary{background:white;color:var(--ink);border-color:var(--line)}button:disabled{opacity:.45;cursor:not-allowed}.muted{color:var(--muted);font-size:12px}.node-options{max-height:315px;overflow:auto;margin:12px 0;border:1px solid var(--line);border-radius:10px}.node-option{padding:11px 12px;margin:0;border-bottom:1px solid #edf1f3;cursor:pointer;font-weight:400}.node-option:last-child{border-bottom:0}.node-option:has(input:disabled){opacity:.6;cursor:default}.node-detail{display:block;color:var(--muted);font-size:11px}.empty{padding:25px 12px;text-align:center;color:var(--muted)}.badge{padding:3px 9px;border-radius:20px;font-size:11px;background:#e9f4f4;color:#08727a;white-space:nowrap}.server-row{padding:18px 0;border-bottom:1px solid var(--line)}.server-title{font-weight:700;font-size:16px}.row-actions{display:flex;gap:8px;margin-top:10px}.server-notes{white-space:pre-wrap;overflow-wrap:anywhere}.search{display:flex;gap:8px;margin-bottom:8px}.pagination{margin-top:20px;font-size:12px}.command-options{display:flex;gap:14px}.command-options label{flex:1;margin-top:0}.command-options select{margin-top:6px}.command{font:12px/1.8 ui-monospace,Consolas,monospace;background:#f4f8f9;overflow-wrap:anywhere}.command-actions{justify-content:start;margin-top:12px;flex-wrap:wrap}#notice:not(:empty){background:#e4f4ef;border:1px solid #aedac9;border-radius:10px;padding:12px 16px;margin-bottom:22px;overflow-wrap:anywhere}#notice.error{background:#fff0ed;border-color:#e7b7ab;color:#a33424}footer{margin-top:30px;color:var(--muted);font-size:12px}[hidden]{display:none!important}details summary{cursor:pointer;color:var(--accent)}@media(max-width:900px){.layout{grid-template-columns:1fr}.card{padding:20px}main{padding:24px 16px}h1{font-size:24px}.command-options{flex-wrap:wrap}}
